<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Bell, Download, Upload } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { api } from '../api'
import type { Application, ApplicationStatus } from '../types'
import { toPayload } from '../utils'
import { useI18n } from '../i18n'
const props=defineProps<{items:Application[]}>(),emit=defineEmits<{refresh:[]}>(),{language}=useI18n(),open=ref(false),fileInput=ref<HTMLInputElement|null>(null)
const active=computed(()=>props.items.filter(i=>!['Rejected','Withdrawn'].includes(i.status)).length),interviews=computed(()=>props.items.filter(i=>i.status==='Interview').length),offers=computed(()=>props.items.filter(i=>i.status==='Offer').length)
const responseRate=computed(()=>{const sent=props.items.filter(i=>i.status!=='Wishlist').length,replied=props.items.filter(i=>['OA','Interview','Offer','Rejected'].includes(i.status)).length;return sent?Math.round(replied/sent*100):0})
function download(name:string,content:string,type='text/plain'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportCSV(){const fields=['company_name','position_name','status','location','deadline_at','applied_at','apply_link','notes'],quote=(v:unknown)=>`"${String(v??'').replace(/"/g,'""')}"`;download('internship-applications.csv',[fields.join(','),...props.items.map(i=>fields.map(f=>quote(i[f as keyof Application])).join(','))].join('\n'),'text/csv')}
function exportICS(){const stamp=(v:string)=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('internship-calendar.ics',`BEGIN:VCALENDAR\nVERSION:2.0\n${props.items.filter(i=>i.deadline_at).map(i=>`BEGIN:VEVENT\nUID:${i.id}\nDTSTART:${stamp(i.deadline_at)}\nSUMMARY:Deadline: ${i.company_name} - ${i.position_name}\nEND:VEVENT`).join('\n')}\nEND:VCALENDAR`,'text/calendar')}
async function importCSV(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const lines=(await file.text()).split(/\r?\n/).filter(Boolean),headers=lines.shift()?.split(',').map(v=>v.replace(/^"|"$/g,''))||[];let count=0;for(const line of lines){const values=line.split(',').map(v=>v.replace(/^"|"$/g,'')),row=Object.fromEntries(headers.map((h,i)=>[h,values[i]||'']));if(!row.company_name||!row.position_name)continue;await api.createApplication(toPayload({company_name:row.company_name,position_name:row.position_name,status:(row.status||'Wishlist') as ApplicationStatus,location:row.location||'',deadline_at:(row.deadline_at||'').slice(0,10),applied_at:(row.applied_at||'').slice(0,16),apply_link:row.apply_link||'',notes:row.notes||'',jd_text:'',resume_version:'',priority:'',salary_min:0,salary_max:0,salary_unit:'',experience_years:0,education:'',work_mode:'',days_per_week:0,intern_months:0,can_convert:false,tech_stack:'',is_liked:false,source_type:'',source_name:'',source_url:'',employment_type:'',department:'',requirements:'',responsibilities:'',contact_name:'',contact_email:''}));count++}ElMessage.success(`${count} applications imported`);emit('refresh')}
async function enableNotifications(){if(!('Notification'in window))return ElMessage.warning('Notifications are not supported by this browser');if(await Notification.requestPermission()==='granted'){localStorage.setItem('it_notifications','on');new Notification('Internship Tracker',{body:'Browser reminders are enabled.'})}}
onMounted(()=>{if(localStorage.getItem('it_notifications')==='on'&&Notification.permission==='granted'){const soon=props.items.find(i=>i.deadline_at&&new Date(i.deadline_at).getTime()>Date.now()&&new Date(i.deadline_at).getTime()-Date.now()<86400000);if(soon)new Notification(`Deadline: ${soon.company_name}`,{body:soon.position_name})}})
</script>
<template><section class="career-tools"><button class="career-tools-toggle" type="button" @click="open=!open"><span><b>{{ language==='en'?'Career insights & data tools':'求职分析与数据工具' }}</b><small>{{ language==='en'?'A quick summary, reminders, imports, and exports':'进度概览、提醒与数据导入导出' }}</small></span><span>{{ open?'−':'+' }}</span></button><div v-if="open" class="career-tools-body"><div class="insight-grid"><div><span>{{ language==='en'?'Active applications':'进行中的申请' }}</span><b>{{ active }}</b></div><div><span>{{ language==='en'?'At interview':'面试阶段' }}</span><b>{{ interviews }}</b></div><div><span>{{ language==='en'?'Offers':'Offer' }}</span><b>{{ offers }}</b></div><div><span>{{ language==='en'?'Response rate':'回复率' }}</span><b>{{ responseRate }}%</b></div></div><section class="data-tools"><h3>{{ language==='en'?'Reminders & data':'提醒与数据' }}</h3><p class="data-tools-intro">{{ language==='en'?'Get deadline alerts and move your tracker data between this app, spreadsheets, and calendar apps.':'接收截止提醒，并在本应用、表格和日历软件之间转移数据。' }}</p><div class="tool-actions"><span><el-button :icon="Bell" @click="enableNotifications">{{ language==='en'?'Enable reminders':'开启提醒' }}</el-button><small>{{ language==='en'?'Alerts you before close deadlines.':'临近截止时通知你。' }}</small></span><span><el-button :icon="Download" @click="exportCSV">{{ language==='en'?'Export CSV':'导出 CSV' }}</el-button><small>{{ language==='en'?'Download applications as a spreadsheet.':'将申请下载为表格。' }}</small></span><span><el-button :icon="Download" @click="exportICS">{{ language==='en'?'Export calendar':'导出日历' }}</el-button><small>{{ language==='en'?'Add deadlines to your calendar app.':'将截止日期加入日历软件。' }}</small></span><span><el-button :icon="Upload" @click="fileInput?.click()">{{ language==='en'?'Import CSV':'导入 CSV' }}</el-button><small>{{ language==='en'?'Add applications from a spreadsheet.':'从表格批量添加申请。' }}</small></span><input ref="fileInput" hidden type="file" accept=".csv" @change="importCSV"/></div></section></div></section></template>
